      "instructionsEn": "Write 3-4 English sentences about something you did on your own or someone you know: use a reflexive pronoun where the subject and object are the same (**I taught myself** ...), a reflexive pronoun for emphasis (**I made it myself**), a sentence with a preposition of place using a personal pronoun (**next to me**) and a sentence with **each other** or **with each other**.",
      "ruleSummary": "Reflexive pronouns (myself, yourself, herself, himself, itself, ourselves, yourselves, themselves; themselves/themself for a person of unknown sex). Use a reflexive pronoun as object when subject and object are the same (She forced herself to eat it vs She forced her to eat it). Reflexives also add emphasis: the subject personally (he came himself), done without help (I made it myself), a noun (the author herself), the subject causing an action (He got himself arrested), or meaning 'also' (I was feeling pretty bad myself). Some verbs rarely or never take a reflexive in English: complain, concentrate, get up/hot/tired, lie down, meet, relax, remember, sit down, wake up (She concentrated hard, not concentrated herself). With shave, undress, wash, dress, acclimatise, adapt, behave, hide, move, the reflexive is used only to emphasise the subject doing it (he is now able to dress himself). After prepositions of place use a personal pronoun (She put her bag next to her), but after prepositions closely linked to the verb use a reflexive when subject and object are the same (pleased with himself; be ashamed of, believe in, care about, do with, hear about, look after, look at, take care of). For reciprocal actions use each other / one another (attract, avoid, complement, embrace, face, fight, help, kiss, marry, meet, repel), and with + each other after agree, coincide, collaborate, compete, contrast, co-operate, disagree, joke, mix, quarrel, talk, communicate. Judge whether each student sentence chooses correctly between reflexive, personal pronoun and each other, and uses with where needed."
