      "ruleSummary": "One and ones as substitutes. Use one instead of repeating a singular countable noun (I've already got one; mine's the big blue one) and ones for a plural noun (his early ones). Not with uncountable nouns (I'll bring you some, not one; he got orange, not orange one). Ones needs additional information (green ones, ones with flowers on); otherwise use some (let's buy some, not let's buy ones). Don't use one after a (I need one, not a one), after nouns used as adjectives (my jacket pocket, not my jacket one), and prefer mine/yours/hers to my one/your one except in informal speech. One/ones can be left out after which, superlatives, this/that/these/those (some consider those ones incorrect), either, neither, another, each, the first/last. It cannot be left out after the, the only, the main, every, or adjectives (some new ones), although after colour adjectives in answers it often can (I'll take the blue (one)). Judge whether each student sentence uses one/ones, some, a possessive pronoun or ellipsis correctly."
