      "instructions": "Hoàn thành câu bằng so. Nếu không thể dùng so, hãy hoàn thành câu bằng một mệnh đề that phù hợp. (B)",
      "instructionsEn": "Complete the sentences with so. If it is not possible, complete the sentence with an appropriate that-clause. (B)",
