      "instructions": "Hoàn thành câu trả lời bằng động từ trong ngoặc và so, not hoặc not (n't)...so cho phù hợp. Nếu có hai cách trả lời, cách nào cũng được chấp nhận. (B & C)",
      "instructionsEn": "Complete the answers using the verb in brackets and so, not, or not (n't)...so, as appropriate. If two answers are possible, either is accepted. (B & C)",
