      "instructionsEn": "Write 3-4 English sentences: one formal sentence using **do so**, **did so** or **doing so** to avoid repeating a verb + object; one using **do** alone after a state verb (such as like, remember); and one using **such** or **such a/an** + noun to refer back to something just mentioned, then rewrite it less formally (a ... like that, this sort of ...).",
      "ruleSummary": "Do so / such as substitutes. Do so (does so, did so, doing so, done so) replaces a verb + object/complement when the meaning is clear from context (She won in 1997 and seems likely to do so again). It is mostly formal; informally we use do it / do that, or do alone especially after modals and perfect tenses (It should do; I have done). Do so is used with dynamic (action) verbs such as vote, confess (84% did so last year), not with state verbs such as like, remember, where we use do alone (John doesn't like Porter's films but I do, not I do so). Such + uncountable/plural noun and such + a/an + singular countable noun refer back to something mentioned, meaning 'of this/that kind' (Such a person was not easy to find; Such behaviour is unacceptable). Such is formal; informal equivalents are a person like this, a scheme of this kind, this sort of behaviour. Judge whether each student sentence uses these substitutes correctly and naturally."
