      "instructionsEn": "Write 3-4 short exchanges (a question or remark and a reply) where the reply leaves out repeated words after an auxiliary: one with **do/does/did** when the first sentence has no auxiliary, one repeating **be** when be is the main verb, and one with a modal + **(do)** or **(be)**.",
      "ruleSummary": "Leaving out words after auxiliary verbs (ellipsis). To avoid repetition we use an auxiliary (be, have, can, will, would, etc.) instead of a whole verb group or verb + what follows (She says she's finished, but I don't think she has; 'Would any of you like to come?' 'I would.'). With several auxiliaries we keep the first, or two or more (his wife had / had been; they could / could have / could have been). With no auxiliary, or with do, we use do (I play chess as well as he does). If be is the main verb we repeat be (They always are). If have is the main verb we use have or do (I think you have / you do), but with have + noun for actions (have a good time) we prefer do (but I did). Auxiliary have can be followed by done (as many restaurants have (done)); a modal can be followed by do in speech (I might (do)). After a modal, be may be left out if be was an auxiliary in a continuous (I think she will (be)), but not if be was a main verb or a passive auxiliary (never will be; The shop had said it would be). Judge whether each reply leaves out the right words and uses the right auxiliary."
