      "instructionsEn": "Write 3-4 short exchanges where the reply leaves out a to-infinitive: one using just **to** (for example I'd love to, I didn't mean to), one that must repeat **to be** because the first sentence uses be, and one with **if you want (to)** or **if you like**, plus a negative such as **I don't want to**.",
      "ruleSummary": "Leaving out to-infinitives. We can use to instead of a whole to-infinitive clause when the meaning is clear (I wanted to come, but I won't be able to; she chose not to). If the earlier clause uses be, we repeat to be (he just pretended to be, not pretended to). After some adjectives and nouns (willing, plans) and the verbs agree, ask, expect, forget, promise, refuse, try, wish we can leave out the whole to-infinitive or keep to (He promised (to)); but negative expect and wish keep to (we didn't expect to). Verbs such as mean, intend, advise + noun, be able, choose, deserve, fail, hate, hope, need, prefer keep to. After want and would like in if- and wh-clauses to is optional (if you want (to); whatever you would like (to)); in other cases to is kept (I would still like to). After like we leave out the to-infinitive (if you like), but negative want, would like and like keep to (I don't really want to; I didn't like to). Judge whether each reply keeps or drops to correctly."
