              "text": "Some adjectives can be used immediately after a noun. These include some *-ible* and *-able* adjectives such as *available*, *imaginable*, *possible*, *suitable*. However, we use these adjectives immediately after a noun only when the noun follows words such as *first*, *last*, *next*, *only* and superlative adjectives, or when a prepositional phrase follows the adjective:",
