      "instructionsEn": "Write 3-4 English sentences: one using an 'a-' adjective (asleep, alive, afraid...) after a linking verb and one using its related adjective before a noun (sleeping, living, frightened...); one with a classifying or emphasising adjective (main, entire, utter...); and one with an adjective immediately after the noun (the people present, the best solution possible...).",
      "ruleSummary": "Adjective position. Most adjectives go before a noun or after a linking verb (appear, be, become, feel, get, seem): the hot sun / the sun was hot. Some are seldom or never used before a noun: 'a-' adjectives (afraid, alight, alike, alive, alone, ashamed, asleep, awake, aware) and health/feeling adjectives (content, fine, glad, ill, poorly, sorry, (un)sure, upset, (un)well), though an adverb + adjective + noun is sometimes possible (a terminally ill patient); sick can go before a noun. Related adjectives go in either position: alive/living, afraid/frightened, alike/similar, asleep/sleeping; (un)happy works in both. Classifying adjectives (atomic, digital, medical, chief, entire, initial, main, only, whole, eventual, occasional, northern, maximum, minimum, underlying) and emphasising adjectives (absolute, complete, mere, utter) are seldom used after a linking verb (a nuclear explosion, not the explosion was nuclear). Some -ible/-able adjectives (available, imaginable, possible, suitable) can follow a noun after first, last, next, only or a superlative, or when a prepositional phrase follows (the only treatment suitable; an offer available to members). Concerned, involved, opposite, present, responsible change meaning: my present address (= now) vs the people present (= there); concerned (= worried) teachers vs the people concerned (= involved). Judge whether each student sentence puts the adjective in a possible position with the intended meaning."
