      "ruleSummary": "Participle adjectives. Many -ing and -ed participles work as adjectives before a noun or after a linking verb (a welcoming cup of tea, a broken plate, the results were pleasing). Some participles go immediately after a noun to identify it, like a defining relative clause (the crowds watching, the rooms used); a few of these rarely go before the noun (the candidates applying, the things taken, also caused, found, provided, used), while others can go either side (the area infected / the infected area, also affected, broken, chosen, identified, interested, remaining, resulting, stolen). With feeling adjectives the -ing form describes the thing causing the feeling (a surprising decision, a pleasing result) and the -ed form describes the person who feels it (I was surprised, the bored children). Compound adjectives join a noun, adverb or adjective to a participle with a hyphen (money-making, well-behaved, newly-built, worried-looking, slow-moving), and some participles only work inside such a compound (not a making enterprise, not a built ship; arrived troops needs recently arrived troops). In formal English that and those can come before a participle (lower than that required by law, advice for those preparing to go on holiday). Judge whether each student sentence places and chooses participle adjectives correctly."
