      "instructionsEn": "Write 3-4 English sentences showing how pairs of adjective + preposition differ in meaning, for example **unfair of / unfair on**, **frightened of / frightened for**, **wrong about / wrong of**, or **afraid of / afraid for**. Include at least one sentence with an -ing verb after the adjective + preposition (**good at hiding**).",
      "ruleSummary": "Prepositions after adjectives whose meaning changes with the preposition: afraid of (fear something) / afraid for (worried about someone's safety); angry or annoyed about something / with somebody; answerable for (responsible for) / answerable to (must explain actions to); anxious about (worried about) / anxious for (want very much); good/bad at (skill) / good/bad for (healthy, beneficial); good about (pleased with oneself), good to (kind), good with (skilful); concerned about (worried) / concerned with (about, dealing with); glad for someone / glad of something (grateful for); pleased about/at something that happened, pleased with a thing or person; right about (correct about) / right for (suitable for); sorry about something / sorry for someone (sympathy); similarly unfair of someone (their behaviour) / unfair on someone (who suffers), frightened of / frightened for, wrong about / wrong of. A verb after adjective + preposition takes the -ing form (famous for holding, anxious about not having, good at hiding), unlike adjective + to-infinitive (right to report, anxious to avoid). Judge whether each student sentence uses the preposition that matches the intended meaning and the correct verb form after it."
