      "instructionsEn": "Write 3-4 English sentences: one comparing two things with an -er or more form, one with an adjective + **enough** or **sufficiently** + to-infinitive, one with **too** + adjective + to-infinitive, and one following the pattern **The ... the ...** (for example The later the election, ...).",
      "ruleSummary": "One-syllable adjectives usually take -er/-est, adjectives of three or more syllables take more/less and most/least. Some two-syllable adjectives normally take more/most: participle adjectives (pleased, worried, boring), -ful and -less adjectives, afraid, alike, alert, ashamed, alone, aware, cautious, certain, complex, confident, eager, exact, formal, frequent, modern, recent; most other two-syllable adjectives take either form (likelier/more likely, commonest/most common, simpler/more simple). Complete, equal, favourite, ideal, unique are rarely compared. Enough goes before nouns but after adjectives (comfortable enough, not enough comfortable; a strong enough position); big enough nails (the nails aren't big enough) differs from enough big nails (not enough of them). Sufficiently goes before the adjective and is more formal (not sufficiently different). Adjective + enough and too + adjective are followed by a to-infinitive, with for + person/thing if needed (strong enough to support the roof; big enough for two cars to fit in; too high for most people to afford). Formally, too + adjective + a/an + noun (too tiring a day, not a too tiring day). The + comparative, the + comparative shows two things changing together (The better the joke, the louder the laugh). Judge whether each student sentence forms the comparative correctly, places enough, sufficiently and too correctly, and uses the right to-infinitive pattern."
