              "kind": "text",
              "text": "Some adverbs of indefinite frequency, which say in an indefinite way how often something happens, usually go in mid position. These include *hardly ever*, *often*, *rarely*, *regularly*, *seldom*, and also *never* and *always* (but see C below):",
