      "instructionsEn": "Write 3-4 English sentences giving your opinion on a recent piece of news or event. Use at least one comment adverb (**Personally**, **Frankly**, **Apparently** ...) or a similar phrase (**To be honest**, **Oddly enough** ...), one viewpoint adverb (**Financially**, **Politically** ...), and one sentence with **even**, **only** or **alone** in the correct position.",
      "ruleSummary": "Comment, viewpoint and focus adverbs. Comment adverbs show how likely we think something is (apparently, clearly, definitely, in theory, obviously, presumably, probably), our attitude to or opinion of what is said (frankly, honestly, luckily, naturally, personally, sadly, surprisingly, unbelievably), or our judgement of someone's actions (bravely, foolishly, kindly, wisely, wrongly). Most can go in front, mid or end position, and they are usually separated by a comma, especially in front and end position. Phrases such as to my disappointment, oddly enough, to be frank, to put it simply work in the same way. Viewpoint adverbs make clear from what point of view we are speaking (financially, physically, politically, technically, environmentally), as do phrases such as morally speaking, in political terms, from a technical point of view. Focus adverbs: even and only usually go in mid position, but come before the subject when they refer to it (Only my mother has brought some food; Even Sue can speak French, not Sue even can). Alone meaning 'only' comes after a noun (by hard work alone; the tickets alone would cost too much). Judge whether each student sentence uses these adverbs with the right meaning and in a natural position."
