      "ruleSummary": "Verb tense in adverbial time clauses (after, as, as soon as, before, until, when, while) and related structures. For present or past time, the time clause uses the same tense as a main clause would; for future time it uses a present tense, not will (Wait here until you're ready; not until you will be ready). For an action completed before the main-clause action, simple or perfect tenses are possible (as soon as you see / have seen her), but the present perfect is preferred for an action over a period of time (After I have written this book, I'm having a holiday). For two actions at the same time, a simple tense is used, not a perfect (When I saw Kim, I asked her...; not When I had seen). Before is used when the main-clause event has little or no duration and doesn't happen until the time in the clause (She walked out before I could explain). Until or before are both possible to say how far away an event is (It was three days until/before the letter arrived) and after a negative main clause; with a positive main clause, until means 'up to the time' and before 'at some time before'; until is used when the clause describes the result (He cleaned his shoes until they shone). Hardly and scarcely take when or before, and no sooner takes than, usually with a past perfect in the first clause and a past simple in the second; in literary style the first clause can be inverted (Scarcely had Mrs James stepped into the classroom when the boys began fighting; No sooner had the runway been built than residents complained). Judge whether each student sentence uses a correct tense in the time clause and the right linking word and word order."
