              "kind": "text",
              "text": "when we want to say that when one thing changes, another thing changes at the same time. However, we prefer **as** to express this meaning:",
              "vi": "khi muốn nói rằng khi một điều thay đổi thì một điều khác cũng thay đổi cùng lúc. Tuy nhiên, để diễn đạt nghĩa này chúng ta thích dùng as hơn:"
