              "text": "We prefer **while** or **as** (rather than *when*) to talk about two longer actions that go on at the same time:",
              "vi": "Chúng ta thích dùng while hoặc as (thay vì when) để nói về hai hành động kéo dài diễn ra cùng lúc:"
