      "ruleSummary": "As, when and while in time clauses. All three can mean 'during the time that' (As/When/While Dave was eating, the doorbell rang). Only when is used for a shorter event happening during a longer one described in the main clause (They were playing in the garden when they heard a scream), one event immediately after another (When the lights went out, I lit some candles), periods of life or past time (when he was a baby), and 'every time' (when I wake up). As or when (not while) is used for two short simultaneous events (as/when you cross the bridge), and as is preferred when one thing changes as another changes (As the cheese matures, its flavour improves). While or as (rather than when) is used for two longer simultaneous actions, and while is used instead of as when as could be read as 'because'. In formal style subject + be can be left out after when/while when both clauses share the subject (when told the news, while digging in the garden, while on the boat), but not when the subjects differ. Judge whether each student sentence chooses a conjunction that fits its meaning and reduces clauses correctly."
