      "instructionsEn": "Write 3-4 English sentences giving reasons for some recent decisions of yours: one with **as** or **since**, one with **because of** or **due to** + a noun, one informal sentence with **seeing that**, and one beginning with **With** (e.g. **With so much work to do, ...**).",
      "ruleSummary": "Giving reasons. As, because, since and seeing that/as begin a clause giving a reason (As it was getting late, I decided to go home). Because can begin a sentence and is the usual choice in speech, where so is also common (My mother's arrived, so I won't be able to meet you); since is rather formal; seeing that/as is informal. For, in that and inasmuch as give reasons in formal or literary writing (The film is unusual in that there are only four actors in it). Because of, due to and owing to are prepositions followed by a noun phrase, not a clause (because of an accident, not because of there was an accident); most people avoid owing to after be (The company's success is largely due to the new director). For can mean 'because of' (all the better for her stay in hospital) but cannot begin a sentence; with means 'because there is/are' and can begin a sentence (With so many people ill, I've decided to cancel the meeting). Judge whether each student sentence uses a reason word that fits its grammar (clause vs noun phrase) and register."
