      "instructions": "Hãy viết 3-4 câu tiếng Anh về việc bạn học tiếng Anh: một câu nêu mục đích với **in order to** hoặc **so as not to**, một câu với **so that** + **can/could**, một câu dùng **for + -ing** để nói công dụng của một thứ bạn dùng khi học, và một câu nhấn mạnh kiểu **So ... was ... that ...**.",
      "instructionsEn": "Write 3-4 English sentences about how you learn English: one giving a purpose with **in order to** or **so as not to**, one with **so that** + **can/could**, one using **for + -ing** for the purpose of something you study with, and one emphatic sentence like **So ... was ... that ...**.",
      "ruleSummary": "Purposes and results. In order to / so as to + infinitive express purpose (He took the course in order to get a better job); in speech a plain to-infinitive is more common. The negative is in order not to / so as not to (so as not to delay the work); a plain 'not to' alone is not used for negative purpose (not ...carefully not to cut myself), but 'not (in order) to X, but (in order) to Y' is fine. In order that / so that + clause also express purpose, so that being more common and less formal, usually with can/could/would (so that she could complete the report; so that the children wouldn't find it). For + noun or to-infinitive gives the purpose of an action (saving for a new car / to buy a new car); for + -ing gives the purpose or definition of a thing (a device used for moving the cursor); to-infinitive gives the use a person makes of something (She used a heavy book to keep the door open). So ... (that) links cause and result (The train was so slow (that) I was two hours late); in formal emphasis So + adjective/adverb goes first with inversion (So slow was the train that...; So quickly did it happen that...); so ... as to + infinitive is also possible (so unusual as to seem a joke). Judge whether each student sentence expresses purpose or result with correct form and word order."
