      "instructionsEn": "Write 3-4 English sentences about a holiday or trip abroad: what you missed or what was disappointing. Use **Much as I ...**, one sentence emphasising an adjective like **Beautiful though it was, ...**, one with **Even though ...** and one with **Despite ...** or **In spite of ...** + -ing or a noun.",
      "ruleSummary": "Contrasts. Although/though introduce an unexpected contrast (Although Reid failed to score himself, he helped Jones score two goals); though is less formal and, unlike although, can be an adverb at the end of a sentence (I'm not keen on yoghurt, though). An adjective or adverb can be fronted before though or as for emphasis, never before although (Hot though/as the night air was, they slept soundly); much as + clause works similarly (Much as I enjoyed the holiday, I was glad to be home). Even though means 'despite the fact that' (the speaker knows it is true) and even if means 'whether or not'; 'even although' is wrong. In spite of / despite are followed by -ing or a noun (In spite of playing with ten men; in spite of their poverty; Despite falling), never by a finite clause, unless the fact that is added (Despite the fact that she fell...). Judge whether each student sentence uses the contrast word with the correct following structure and meaning."
