              "kind": "text",
              "text": "In some unreal conditionals we use *mixed tenses*. That is, a past tense in the if-clause and **would have + past participle** in the main clause, or a past perfect in the if-clause and **would + bare infinitive** in the main clause:",
              "vi": "Trong một số câu điều kiện không có thật, ta dùng thì hỗn hợp: thì quá khứ trong mệnh đề if và would have + quá khứ phân từ trong mệnh đề chính, hoặc quá khứ hoàn thành trong mệnh đề if và would + động từ nguyên mẫu không to trong mệnh đề chính:"
