      "instructionsEn": "Write 3-4 English conditional sentences about your own life: one real conditional about the future (**If I finish early, I'll...**), one unreal conditional about the present (**If I had more time, I would...**), one unreal conditional about the past (**If I had known..., I wouldn't have...**), and, if you can, one with mixed tenses.",
      "ruleSummary": "Conditional sentences and verb tenses. Real conditionals describe situations that are, were or may become true (If anyone phones, tell them I'll be back at 11.00); they use tenses as in other sentences: present tenses for the present or unchanging relationships (If water is frozen, it expands), past tenses for the past (If I made the wrong decision then I apologise), and a present tense, not will, in the if-clause for the future (I'll give you a lift if it rains, not if it will rain). Unreal conditionals describe imaginary or untrue situations: for present or future situations use a past tense (simple or continuous) in the if-clause and would + bare infinitive in the main clause (If my grandfather was/were still alive, he would be a hundred today); for past situations that didn't happen use if + past perfect and would have + past participle (If I had known how difficult the job was, I wouldn't have taken it). Could/might/should (have) can replace would (have). Mixed tenses are possible: past tense + would have + past participle (If Bob wasn't so lazy, he would have passed the exam) or past perfect + would + bare infinitive (If the doctor had been called earlier, she would still be alive today). In unreal conditionals the main clause does not use the past simple or past perfect (not we spent / we had spent), and the if-clause does not normally use would (not If I would have...). Judge whether each student sentence chooses real or unreal forms matching its meaning and uses the correct tense in each clause."
