      "instructions": "Hãy viết 3-4 câu đúng sự thật về cuộc đời bạn, bắt đầu bằng **But for...**, **If it hadn't been for...** và **Had it...** (như phần cuối bài 100.2 trong sách). Có thể thêm một câu với **If you happen to...** hoặc một lời yêu cầu lịch sự với **If you would...**.",
      "instructionsEn": "Write 3-4 true sentences about your life beginning with **But for...**, **If it hadn't been for...** and **Had it...** (as in the last part of exercise 100.2 in the book). You can add one sentence with **If you happen to...** or a polite request with **If you would...**.",
      "ruleSummary": "Further conditional patterns. If...were + to-infinitive talks about imaginary future situations (If the technology were to become available, we would expand), but not with state verbs such as know, like, remember, understand (If I knew they were honest, not If I were to know); it can also make a suggestion more polite (If you were to move over, we could all sit on the sofa). When the first verb of the if-clause is should, were or had, if can be left out and the verb put first, mainly in formal English (Should any of this cost you anything, send me the bill; Were she to find out the truth; Had they not rushed Dan to hospital). If it was/were not for + noun says one situation depends on another or on a person; for the past use If it had not been for + noun; formal alternatives are Were it not for... and Had it not been for...; but for + noun has a similar meaning (But for Jim's support, I wouldn't have got the job). If...will is not normally used in conditionals, but is possible when the if-clause is a result of the main clause (Open a window if it will help you to sleep, but not I will be angry if it will turn out that you are wrong) and in requests (If you will take your seats...), with if...would being more polite. If...happen to, if...should and if...should happen to describe something possible but not very likely in real conditionals (If you happen to be in our area, drop in), not in unreal conditionals about impossible situations (If the North Sea froze, not happened to freeze). Judge whether each student sentence uses these patterns correctly and naturally."
